+import { lookup } from 'node:dns/promises';
+import ipaddr from 'ipaddr.js';
+import { IngestError } from './errors';
+
+const MAX_BYTES = 20 * 1024 * 1024;
+
+async function assertPublicHost(url: URL): Promise<void> {
+  if (url.protocol !== 'https:') {
+    throw new IngestError('only https URLs are supported');
+  }
+  const addresses = await lookup(url.hostname, { all: true });
+  for (const { address } of addresses) {
+    if (ipaddr.parse(address).range() !== 'unicast') {
+      throw new IngestError(`refusing to fetch from ${url.hostname}`);
+    }
+  }
+}
+
+export async function fetchRemoteDocument(rawUrl: string): Promise<Buffer> {
+  const url = new URL(rawUrl);
+  await assertPublicHost(url);
+  const res = await fetch(url, { signal: AbortSignal.timeout(15_000) });
+  if (!res.ok || !res.body) {
+    throw new IngestError(`fetch failed with status ${res.status}`);
+  }
+  const chunks: Buffer[] = [];
+  let total = 0;
+  for await (const chunk of res.body as unknown as AsyncIterable<Uint8Array>) {
+    total += chunk.byteLength;
+    if (total > MAX_BYTES) {
+      throw new IngestError('document exceeds 20 MB');
+    }
+    chunks.push(Buffer.from(chunk));
+  }
+  return Buffer.concat(chunks);
+}
