+import { DynamoDBDocumentClient, GetCommand, UpdateCommand } from '@aws-sdk/lib-dynamodb';
+
+export class ToolBudgetExceeded extends Error {}
+
+export class ToolBudget {
+  constructor(
+    private readonly ddb: DynamoDBDocumentClient,
+    private readonly table: string,
+    private readonly maxCallsPerConversation: number,
+  ) {}
+
+  async consume(conversationId: string): Promise<number> {
+    const key = { pk: `conv#${conversationId}` };
+    const { Item } = await this.ddb.send(new GetCommand({ TableName: this.table, Key: key }));
+    const used = (Item?.toolCallsUsed as number | undefined) ?? 0;
+    if (used >= this.maxCallsPerConversation) {
+      throw new ToolBudgetExceeded(`conversation ${conversationId} used ${used} tool calls`);
+    }
+    await this.ddb.send(
+      new UpdateCommand({
+        TableName: this.table,
+        Key: key,
+        UpdateExpression: 'SET toolCallsUsed = :n, updatedAt = :t',
+        ExpressionAttributeValues: { ':n': used + 1, ':t': new Date().toISOString() },
+      }),
+    );
+    return used + 1;
+  }
+}
