+import type { PlanCode } from '../billing/planLimits';
+import type { Tenant } from '../tenants/types';
+import { usageStore } from '../billing/usageStore';
+import { QuotaExceededError } from './errors';
+
+function monthlyTokenAllowance(plan: PlanCode): number {
+  switch (plan) {
+    case 'starter':
+      return 2_000_000;
+    case 'growth':
+      return 10_000_000;
+    case 'scale':
+      return 60_000_000;
+  }
+}
+
+export async function assertTokenBudget(tenant: Tenant, estimatedTokens: number): Promise<void> {
+  const limit = monthlyTokenAllowance(tenant.plan);
+  const used = await usageStore.tokensThisPeriod(tenant.id);
+  if (used + estimatedTokens > limit) {
+    throw new QuotaExceededError('Monthly token allowance reached', { used, limit });
+  }
+}
