+import { differenceInCalendarDays } from 'date-fns';
+import type { Subscription } from './types';
+
+export const ANNUAL_REFUND_WINDOW_DAYS = 14;
+
+export function refundableAmountCents(sub: Subscription, now: Date): number {
+  if (sub.interval !== 'year') return 0;
+  const daysSincePurchase = Math.max(0, differenceInCalendarDays(now, sub.purchasedAt));
+  if (daysSincePurchase > ANNUAL_REFUND_WINDOW_DAYS) return 0;
+  const termDays = differenceInCalendarDays(sub.currentPeriodEnd, sub.purchasedAt);
+  const unusedDays = Math.max(0, termDays - daysSincePurchase);
+  return Math.floor((sub.amountPaidCents * unusedDays) / termDays);
+}

