+import {
+  GetCommand,
+  TransactWriteCommand,
+  type DynamoDBDocumentClient,
+} from '@aws-sdk/lib-dynamodb';
+import { TransactionCanceledException } from '@aws-sdk/client-dynamodb';
+
+export type ChangeHandleResult = 'ok' | 'taken' | 'unchanged';
+
+export async function changeHandle(
+  ddb: DynamoDBDocumentClient,
+  table: string,
+  userId: string,
+  currentHandle: string,
+  requested: string,
+): Promise<ChangeHandleResult> {
+  const next = requested.trim().toLowerCase();
+  if (next === currentHandle) return 'unchanged';
+
+  // Fast path so the form can say "taken" without starting a transaction.
+  const existing = await ddb.send(
+    new GetCommand({ TableName: table, Key: { pk: `handle#${next}`, sk: 'claim' } }),
+  );
+  if (existing.Item && existing.Item.userId !== userId) return 'taken';
+
+  try {
+    await ddb.send(
+      new TransactWriteCommand({
+        TransactItems: [
+          {
+            Put: {
+              TableName: table,
+              Item: { pk: `handle#${next}`, sk: 'claim', userId },
+              ConditionExpression: 'attribute_not_exists(pk)',
+            },
+          },
+          {
+            Delete: {
+              TableName: table,
+              Key: { pk: `handle#${currentHandle}`, sk: 'claim' },
+              ConditionExpression: 'userId = :uid',
+              ExpressionAttributeValues: { ':uid': userId },
+            },
+          },
+          {
+            Update: {
+              TableName: table,
+              Key: { pk: `user#${userId}`, sk: 'profile' },
+              UpdateExpression: 'SET handle = :h',
+              ConditionExpression: 'handle = :old',
+              ExpressionAttributeValues: { ':h': next, ':old': currentHandle },
+            },
+          },
+        ],
+      }),
+    );
+    return 'ok';
+  } catch (err) {
+    if (err instanceof TransactionCanceledException) return 'taken';
+    throw err;
+  }
+}

