+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import type { ToolDefinition, ToolContext } from './types';
+
+const WORKSPACE_ROOT = process.env.WORKSPACE_ROOT ?? '/mnt/workspaces';
+const MAX_BYTES = 256 * 1024;
+
+export const readFileTool: ToolDefinition<{ path: string }> = {
+  name: 'read_file',
+  description: 'Read a UTF-8 text file from the conversation workspace.',
+  inputSchema: {
+    type: 'object',
+    properties: { path: { type: 'string', description: 'Path relative to the workspace root' } },
+    required: ['path'],
+  },
+  async run(input, ctx: ToolContext) {
+    const root = path.join(WORKSPACE_ROOT, ctx.workspaceId);
+    const target = path.resolve(root, input.path);
+    if (!target.startsWith(root)) {
+      return { isError: true, content: 'Path is outside the workspace.' };
+    }
+    const stat = await fs.stat(target).catch(() => null);
+    if (!stat || !stat.isFile()) {
+      return { isError: true, content: `No such file: ${input.path}` };
+    }
+    if (stat.size > MAX_BYTES) {
+      return { isError: true, content: `File is larger than ${MAX_BYTES} bytes.` };
+    }
+    return { isError: false, content: await fs.readFile(target, 'utf8') };
+  },
+};
