+// SRCH-41: as-you-type search. Every term is matched as a prefix, so
+// "rep q3" finds "Quarterly report Q3". Terms are ANDed.
+const MAX_TERMS = 8;
+
+export function toPrefixTsquery(input: string): string | null {
+  const terms = input
+    .normalize('NFKC')
+    .split(/\s+/)
+    .map((t) => t.replace(/[^\p{L}\p{N}]/gu, '').toLowerCase())
+    .filter((t) => t.length > 0)
+    .slice(0, MAX_TERMS);
+  return terms.length === 0 ? null : terms.map((t) => `${t}:*`).join(' & ');
+}
